def render_dashboard_fixture() -> dict[Path, str]:
    """Run the full refund-failure pipeline and return the dashboard bundle, unwritten.

    Runs run-pipeline in a temp dir, then normalizes the run_id and timestamps to stable
    sentinel values so the bundle never changes across re-runs (only pipeline or schema
    changes should update it). Returns destination path -> file content.
    """
    import tempfile

    from trace_harness.cli import main as cli_main

    with tempfile.TemporaryDirectory(prefix="trace_fixture_gen_") as tmp:
        runs_dir = Path(tmp) / "runs"
        rc = cli_main(["--runs-dir", str(runs_dir), "run-pipeline", str(DASHBOARD_TASKS_PATH)])
        if rc != 0:
            raise RuntimeError(f"run-pipeline exited {rc}")

        run_dirs = sorted(p for p in runs_dir.iterdir() if p.is_dir())
        if not run_dirs:
            raise RuntimeError("no run directory produced")
        src_dir = run_dirs[0]
        real_run_id = src_dir.name

        rendered = {}
        for artifact_name in DASHBOARD_ARTIFACTS:
            artifact = src_dir / artifact_name
            if not artifact.is_file():
                raise RuntimeError(f"run-pipeline did not produce {artifact_name}")
            rendered[DASHBOARD_FIXTURE_DIR / artifact_name] = _normalize_artifact(
                artifact, real_run_id
            )
        return rendered


def render_sample_results() -> dict[Path, str]:
    return {
        OUTPUT_DIR / "sample_passing_result.json": json.dumps(build_passing_scenario(), indent=2)
        + "\n",
        OUTPUT_DIR / "sample_failing_result.json": json.dumps(build_failing_scenario(), indent=2)
        + "\n",
    }


def write_outputs(outputs: dict[Path, str]) -> None:
    for path, content in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"[OK] {path.relative_to(REPO_ROOT)}")
    print(f"     dashboard run_id normalized to: {FIXTURE_RUN_ID}")


def check_outputs(outputs: dict[Path, str]) -> int:
    """Diff rendered outputs against the committed files; 1 if any differ or are missing."""
    stale = []
    for path, generated in outputs.items():
        rel = path.relative_to(REPO_ROOT)
        committed = path.read_text(encoding="utf-8") if path.is_file() else ""
        if committed == generated:
            continue
        stale.append(rel)
        sys.stdout.writelines(
            difflib.unified_diff(
                committed.splitlines(keepends=True),
                generated.splitlines(keepends=True),
                fromfile=f"{rel} (committed)",
                tofile=f"{rel} (generated now)",
            )
        )

    if not stale:
        print(f"[OK] all {len(outputs)} generated files match the committed copies")
        return 0
    print(f"\n[STALE] {len(stale)} committed file(s) differ from what the pipeline emits now:")
    for rel in stale:
        print(f"  {rel}")
    print("Regenerate with `python scripts/generate_sample_outputs.py` and commit the result.")
    return 1


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Generate static sample artifacts.")
    parser.add_argument(
        "--check",
        action="store_true",
        help="write nothing; exit 1 if any committed output differs from a fresh render",
    )
    args = parser.parse_args(argv)

    outputs = {**render_sample_results(), **render_dashboard_fixture()}
    if args.check:
        return check_outputs(outputs)
    write_outputs(outputs)
    return 0


if __name__ == "__main__":
    sys.exit(main())

